<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import AccountingSelect from './AccountingSelect.vue';import AccountingDocument from './AccountingDocument.vue';import {useAccountingPermissions} from './permissions';
const props=defineProps<{company:number;book:any;accounts:any[];csrf?:string}>(),emit=defineEmits(['notice']),can=useAccountingPermissions();
const rows=ref<any>(null),editor=ref<any>(null),search=ref(''),status=ref(''),page=ref(1),busy=ref(false),loading=ref(false),error=ref(''),formError=ref('');let generation=0;
const income=computed(()=>props.accounts.filter(a=>a.active&&!a.is_group&&a.root_type==='Income'));
const costs=computed(()=>props.accounts.filter(a=>a.active&&!a.is_group&&!a.imprest_fund&&['Expense','Asset'].includes(a.root_type)&&!['Cash','Bank','Receivable','Payable'].includes(a.account_type)));
const money=(n:any)=>Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
async function api(path:string,body?:any){const r=await fetch('/accounting/api/'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to save item.');return d;}
async function load(){const g=++generation;loading.value=true;error.value='';try{const d=await api('items?'+new URLSearchParams({company_id:String(props.company),page:String(page.value),search:search.value,status:status.value}));if(g===generation)rows.value=d;}catch(e){error.value=(e as Error).message;}finally{if(g===generation)loading.value=false;}}
watch(()=>props.company,()=>{editor.value=null;page.value=1;void load();},{immediate:true});
function open(item?:any){formError.value='';editor.value=item?{...item}:{company_id:props.company,code:'',name:'',kind:'service',unit:'Service',description:'',sale_rate:'0.00',purchase_rate:'0.00',sellable:true,purchasable:true,income_account_id:null,expense_account_id:null,active:true};}
async function save(){if(busy.value)return;busy.value=true;formError.value='';try{const result=await api('items',{...editor.value,company_id:props.company});emit('notice',result.message);editor.value=null;await load();}catch(e){formError.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section :class="{'ac-document-open':!!editor}"><div class="ac-section-heading"><div><h2>Items & Services</h2><p class="muted">Company catalogue for invoice and order entry. Rates are in {{book?.currency||'the company base currency'}}.</p></div><button v-if="can('items.create')" class="button primary" @click="open()">+ Create item / service</button></div><p v-if="error" class="notice admin-error">{{error}}</p>
<form class="ac-filters" @submit.prevent="page=1;load()"><label>Search<input v-model="search" type="search" placeholder="Item code or name"></label><label>Status<AccountingSelect><select v-model="status"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></AccountingSelect></label><button class="button" :disabled="loading">Apply filters</button></form><p v-if="loading" role="status">Loading catalogue...</p><div v-else-if="rows" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Code / item</th><th>Type / unit</th><th class="numeric">Sales rate</th><th class="numeric">Purchase rate</th><th>Usage</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in rows.data" :key="item.id"><td><strong>{{item.name}}</strong><small>{{item.code}}</small></td><td>{{item.kind}}<small>{{item.unit}}</small></td><td class="numeric">{{money(item.sale_rate)}}</td><td class="numeric">{{money(item.purchase_rate)}}</td><td>{{[item.sellable?'Sales':'',item.purchasable?'Purchases':''].filter(Boolean).join(' / ')||'Not enabled'}}</td><td><span class="ac-badge" :class="item.active?'active':'inactive'">{{item.active?'Active':'Inactive'}}</span></td><td><button v-if="can('items.update')" class="button" @click="open(item)">Edit item</button></td></tr><tr v-if="!rows.data.length"><td colspan="7" class="ac-empty-small">No items or services found.</td></tr></tbody></table></div><div v-if="rows" class="ac-pagination"><span>Page {{page}} of {{rows.last_page}} · {{rows.total}} items</span><button class="button" :disabled="loading||page<=1" @click="page--;load()">Previous</button><button class="button" :disabled="loading||page>=rows.last_page" @click="page++;load()">Next</button></div>
<AccountingDocument v-if="editor" :title="editor.id?'Edit item / service':'Create item / service'" :busy="busy" @close="editor=null"><p class="ac-help">Catalogue entries do not post to the ledger or change stock. Inactive items stay in historical documents and cannot be selected for new entries.</p><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><form @submit.prevent="save"><fieldset class="ac-journal-fields" :disabled="busy"><div class="ac-form-grid"><label>Item code<input v-model="editor.code" required maxlength="50"></label><label>Name<input v-model="editor.name" required maxlength="150"></label><label>Type<AccountingSelect><select v-model="editor.kind"><option value="service">Service</option><option value="product">Product</option></select></AccountingSelect></label><label>Unit<input v-model="editor.unit" required maxlength="30" placeholder="Service / hour / piece"></label><label>Default sales rate<input v-model="editor.sale_rate" inputmode="decimal" required pattern="[0-9]{1,10}(\.[0-9]{1,2})?" placeholder="0.00"></label><label>Default purchase rate<input v-model="editor.purchase_rate" inputmode="decimal" required pattern="[0-9]{1,10}(\.[0-9]{1,2})?" placeholder="0.00"></label><label>Default income account<AccountingSelect><select v-model="editor.income_account_id"><option :value="null">Choose at invoice entry</option><option v-for="a in income" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label><label>Default expense / asset account<AccountingSelect><select v-model="editor.expense_account_id"><option :value="null">Choose at invoice entry</option><option v-for="a in costs" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label><label>Description<textarea v-model="editor.description" rows="2" maxlength="250"></textarea></label><div><label class="ac-check"><input v-model="editor.sellable" type="checkbox">Available for sales</label><label class="ac-check"><input v-model="editor.purchasable" type="checkbox">Available for purchases</label><label class="ac-check"><input v-model="editor.active" type="checkbox">Active</label></div></div></fieldset><div class="ac-form-actions"><button class="button" type="button" :disabled="busy" @click="editor=null">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Saving...':'Save item / service'}}</button></div></form></AccountingDocument></section></template>
